'use strict';
// Login presentation only. The existing form, inputs, submit handler and logo
// are retained; no authentication or business API is replaced.
window.Login46={
 mounted:false,
 copy:{register:['账号注册申请','Request an Account'],title:['产品仓储管理系统','Product Warehouse Management System'],project:['穆松尼项目','Musonoi Project'],products:['阴极铜 · 氢氧化钴','Copper Cathodes · Cobalt Hydroxide'],welcome:['欢迎使用','Welcome'],account:['账号','Account'],password:['密码','Password'],signIn:['登录','Log In']},
 text(zh,en){return window.I18n?.language==='en'?en:zh;},
 node(tag,cls,parent){const node=document.createElement(tag);node.className=cls;if(parent)parent.append(node);return node;},
 label(node,key){if(!node)return;node.dataset.loginCopy=key;node.dataset.noI18n='';},
 mount(){if(this.mounted)return;const panel=document.getElementById('login-panel'),card=panel?.querySelector('.login-card'),form=document.getElementById('login-form');if(!panel||!card||!form)return;this.mounted=true;panel.classList.add('login46');panel.dataset.loginLayout='reference';
  const art=this.node('div','login46-art',panel);art.setAttribute('aria-hidden','true');const geology=this.node('img','login46-geology',art);geology.src='/assets/login-geology-v1.png';geology.alt='';geology.width=1776;geology.height=887;
  const head=this.node('div','login46-head');panel.prepend(head);const logo=card.querySelector('.login-logo');if(logo)head.append(logo);
  const languages=this.node('nav','login46-languages',head);languages.setAttribute('aria-label','系统语言 / System Language');const languageLabel=this.node('span','login46-language-label',languages);languageLabel.textContent='系统语言 / System Language';languageLabel.dataset.noI18n='';const choices=this.node('div','login46-language-choices',languages);for(const [code,title]of [['zh-CN','中文'],['en','English']]){const button=this.node('button','',choices);button.type='button';button.textContent=title;button.dataset.loginLanguage=code;button.dataset.noI18n='';button.onclick=async()=>{await I18n.change(code);this.refresh();};}
  const brand=this.node('section','login46-brand');card.before(brand);const title=card.querySelector('h1');if(title){brand.append(title);this.label(title.querySelector('.login46-title-text'),'title');}const project=card.querySelector('.login-project');if(project){brand.append(project);this.label(project,'project');}
  const welcome=this.node('div','login46-welcome');card.prepend(welcome);this.label(this.node('h2','',welcome),'welcome');
  for(const [id,key]of [['login-username','account'],['login-password','password']]){const input=document.getElementById(id),label=input?.closest('label');if(!input||!label)continue;const text=[...label.childNodes].find(n=>n.nodeType===Node.TEXT_NODE&&n.textContent.trim()),span=this.node('span','login46-field-label');this.label(span,key);if(text)text.replaceWith(span);else label.prepend(span);input.dataset.noI18n='';}
  const password=document.getElementById('login-password');if(password){const row=this.node('span','login46-password-row');password.before(row);row.append(password);const toggle=this.node('button','login46-password-toggle',row);toggle.type='button';toggle.setAttribute('aria-controls','login-password');toggle.setAttribute('aria-pressed','false');toggle.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="login46-eye-slash" d="m4 3 16 18"/></svg>';toggle.onclick=()=>{const show=password.type==='password';password.type=show?'text':'password';toggle.setAttribute('aria-pressed',String(show));this.refresh();};}
  const submit=form.querySelector('button[type=submit]');if(submit){const text=[...submit.childNodes].find(n=>n.nodeType===Node.TEXT_NODE),span=this.node('span','login46-submit-label');this.label(span,'signIn');if(text)text.replaceWith(span);else submit.prepend(span);submit.insertAdjacentHTML('beforeend','<svg viewBox="0 0 28 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M2 12h23M17 4l8 8-8 8"/></svg>');}
  const registration=this.node('button','login46-registration',card);registration.type='button';this.label(registration,'register');registration.onclick=()=>RegistrationUI.open();
  const footer=this.node('div','login46-footer',panel);footer.setAttribute('role','contentinfo');for(const selector of ['[data-login-copyright]']){const node=card.querySelector(selector);if(node)footer.append(node);}
  window.addEventListener('session-expired',()=>{if(password)password.type='password';this.refresh();});this.refresh();
 },
 refresh(){const panel=document.getElementById('login-panel');if(!panel||!this.mounted)return;const en=I18n.language==='en',notice=panel.querySelector('.wms-session-notice');if(notice?.children.length===2){notice.children[0].textContent=this.text('账号已在其他设备登录','Signed In on Another Device');notice.children[1].textContent=this.text('当前会话已结束。请重新登录继续办理。','This session ended. Sign in again to continue.');}const version=panel.querySelector('.login46-title-version'),release=window.AppConfig?.displayVersion||window.ClientRelease?.displayVersion;if(version&&release)version.textContent='V'+release;for(const node of panel.querySelectorAll('[data-login-copy]')){const text=this.copy[node.dataset.loginCopy];if(text)node.textContent=text[en?1:0];}for(const button of panel.querySelectorAll('[data-login-language]'))button.setAttribute('aria-pressed',String(button.dataset.loginLanguage===I18n.language));for(const [id,zh,english]of [['login-username','请输入账号','Enter your account'],['login-password','请输入密码','Enter your password']]){const input=document.getElementById(id);if(input){input.placeholder=this.text(zh,english);input.setAttribute('aria-label',this.text(id==='login-username'?'账号':'密码',id==='login-username'?'Account':'Password'));}}const password=document.getElementById('login-password'),toggle=panel.querySelector('.login46-password-toggle');if(toggle&&password){const show=password.type==='text';toggle.setAttribute('aria-label',this.text(show?'隐藏密码':'显示密码',show?'Hide password':'Show password'));toggle.setAttribute('aria-pressed',String(show));}}
};
